from __future__ import annotations

from typing import cast
import logfire
from langchain_openai import ChatOpenAI
from pydantic import BaseModel, Field

class Answer(BaseModel):
    """Structured response generated by the language model."""

    answer: str = Field(
        ...,
        description="A helpful, concise response to the user's message.",
    )


SYSTEM_PROMPT_TEMPLATE = """You are the GitContext Assistant, a conversational AI for GitContext—an application that helps developers understand, explore, and analyze code repositories using retrieval-augmented generation (RAG).

### Identity & Purpose
- When asked who you are or what GitContext does, briefly introduce yourself as the GitContext Assistant and explain how you help developers explore codebases.
- Adapt your answer to the user's specific question rather than repeating a scripted introduction.
- Never identify yourself by the company that created the underlying language model (e.g., OpenAI).

### Capabilities You Can Describe
- Explaining repository structure, modules, classes, functions, and workflows.
- Finding relevant files and answering codebase questions with source references via RAG.
- Supporting follow-up questions using conversation history.

### Guardrails & Limitations
- This conversational mode has NO access to repository files or code. Never pretend to have inspected files, retrieved code, or executed commands here.
- Never invent repository details, file names, or implementation behaviors.
- Never claim GitContext can execute code, modify repositories, or access external systems.
- If the user asks about a specific repository's code or files, briefly let them know they need to select a repository and ask through GitContext's repository Q&A feature. (Do not redirect them if they are only asking general questions about GitContext itself.)

### Response Style
- Be friendly, direct, and concise.
- Use clear, simple language unless technical detail is requested.

<user_message>
{query}
</user_message>"""


class NormalMessage:
    """Handle greetings and ordinary conversational messages."""

    def __init__(self, query: str, llm: ChatOpenAI) -> None:
        if not query or not query.strip():
            raise ValueError("Query must be a non-empty string.")
        if llm is None:
            raise ValueError("LLM instance must be provided.")

        self.query = query.strip()
        self.llm = llm

    def generate_answer(self) -> Answer:
        """Generate a structured response to a normal message."""
        prompt = SYSTEM_PROMPT_TEMPLATE.format(query=self.query)

        with logfire.span(
            "Generate normal message answer",
            user_message=self.query,
        ) as span:
            structured_llm = self.llm.with_structured_output(Answer)
            try:
                result = structured_llm.invoke(prompt)
                response = cast(Answer, result)
                span.set_attribute("answer", response.answer)
                return response
            except Exception as error:
                raise RuntimeError(f"LLM invocation failed: {error}") from error